import base64
from io import BytesIO
from PIL import Image
import gradio as gr

def base64_to_image(b64_string: str):
    """
    Convert a Base64-encoded string to a PIL image.
    
    If the string includes a data URI scheme (e.g. "data:image/png;base64,..."),
    then the header is removed before decoding.
    """
    # Remove data header if it exists
    if b64_string.startswith("data:image"):
        try:
            b64_string = b64_string.split(",")[1]
        except IndexError:
            return "Error: Incorrect data URI format."

    try:
        # Decode the Base64 string to binary data
        image_data = base64.b64decode(b64_string)
    except Exception as e:
        return f"Error decoding Base64: {str(e)}"

    try:
        # Open the image from binary data
        image = Image.open(BytesIO(image_data))
        # Optionally, convert to RGB if image is in another mode
        if image.mode != "RGB":
            image = image.convert("RGB")
        return image
    except Exception as e:
        return f"Error converting decoded data to image: {str(e)}"

# Create the Gradio interface
demo = gr.Interface(
    fn=base64_to_image,
    inputs=gr.Textbox(
        lines=10,
        placeholder="Enter your Base64 string here..."
    ),
    outputs="image",
    title="Base64 to Image Converter",
    description="Paste a Base64 encoded string (with or without the data URI header) to convert it into an image.",
    examples=[
        [""],
        [""],
    ]
)

if __name__ == "__main__":
    demo.launch()
